(()=>{const root=document.querySelector('[data-direction-lab]');if(!root)return;const fit=()=>{const scale=Math.min((window.innerWidth-80)/1400,(window.innerHeight-120)/1040);const gutter=Math.min(72,Math.max(20,window.innerWidth*.04));root.style.setProperty('--direction-fit',String(scale));root.style.setProperty('--direction-layout-width',((window.innerWidth-gutter*2)/scale)+'px');};fit();window.addEventListener('resize',fit,{passive:true});})();